export const Controlled: Story = {
  parameters: { docs: { source: { type: "code" }}},
  render: () => {
    const [singleValue, setSingleValue] = React.useState<Date | null>(
      new Date(2000, 0, 1)
    );
    const [rangeValue, setRangeValue] = React.useState<Date[] | null>([
      new Date(2000, 0, 1),
      new Date(2000, 0, 10),
    ]);
    return (
      <Stack spacing="2-x" className="w-288">
        <DatePicker
          value={singleValue}
          onChange={(val: any) => setSingleValue(val)}
        />
        <DatePicker
          range
          value={rangeValue}
          onChange={(val: any) => setRangeValue(val)}
        />
        <Button
          variant="primary"
          onClick={() => {
            setSingleValue(null);
            setRangeValue(null);
          }}
        >
          reset
        </Button>
      </Stack>
    );
  },
};

export const CustomFormat: Story = {
  parameters: { docs: { source: { type: "code" }}},
  render: () => {
    const [isValid, setValid] = React.useState(true);
    // memoized Intl.DateTimeFormat instance
    const intl = React.useMemo(
      () => new Intl.DateTimeFormat("en-US", { month: "short" }),
      []
    );
    const datePattern = "[0-9]{2}-[a-zA-Z]{3}-[0-9]{4}";
    // custom date to string formatter function
    const formatDateToString = (
      date: Date,
      separator: string,
      locale: string
    ) => {
      // format month as short string representation through Intl API
      const parts = intl.formatToParts(date);
      const monthPart = parts.find((part) => part.type === "month");
      if (!monthPart) return "";
      // format day on two letters
      let day = `${date.getDate()}`;
      if (day.length === 1) day = `0${day}`;
      return `${day}${separator}${
        monthPart.value
      }${separator}${date.getFullYear()}`;
    };
    // custom string to date formatter function
    const formatStringToDate = (
      inputValue: string,
      separator: string,
      locale: string
    ) => {
      return new Date(inputValue);
    };
    return (
      <FormControl
        className="w-288"
        helpText="Example: 01-Jan-2023"
        errorText="Required format: dd-MMM-yyyy (eg. 01-Jan-2023)"
        error={!isValid}
      >
        <DatePicker
          dateFormat="dd-MMM-yyyy"
          datePattern={datePattern}
          dateSeparator="-"
          formatDateToString={formatDateToString}
          formatStringToDate={formatStringToDate}
          locale="en-US"
          onValidation={(valid: boolean) => setValid(valid)}
        />
      </FormControl>
    );
  },
};
